#!/usr/bin/env python3
"""Generate the radar map's base layer from Natural Earth's public-domain vectors.

The map's rain comes from DWD (a WMS image, georeferenced by construction). What goes under it
is coastline and country borders, drawn in QML from this file — vendored rather than fetched,
because no map provider is configured here and a radar map that needs a second network
round-trip to become legible is a worse radar map.

    python test/fixtures/make-basemap.py            # writes qml/Basemap.js

Source: Natural Earth 1:50m, public domain (no attribution required, though the project is
worth crediting). Two things keep the file small enough to sit in a plugin:

  * the data is clipped to the box the radar can ever be drawn over — the view centre is
    clamped to DWD's coverage and the widest view reaches about eleven degrees beyond it, so
    anything outside roughly lon -10..30, lat 34..68 can never be on screen;
  * coordinates are rounded to two decimals, which is about a kilometre and collapses the
    duplicates the generalisation leaves behind.

Segments are kept or dropped by their bounding box, exactly as `Model.svgPath` does at
runtime: at this generalisation a coastline's points are kilometres apart, and the segment
that crosses a whole window can have both its ends outside it.

1:110m was the first choice and it was the wrong one: around Leiden it has one segment
crossing the entire window, which draws a Netherlands with one line across it.
"""

import json
import pathlib
import urllib.request

HERE = pathlib.Path(__file__).resolve().parent
TARGET = HERE.parent.parent / "qml" / "Basemap.js"

SOURCES = {
    "land": "https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_50m_land.geojson",
    "borders": "https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_50m_admin_0_boundary_lines_land.geojson",
}

# lon -10..30, lat 34..68: DWD's coverage, plus the most a widest zoom can reach past it.
CLIP = (-10.0, 34.0, 30.0, 68.0)
DECIMALS = 2


def rings(geometry: dict) -> list:
    """Every ring/line in a (Multi)Polygon or (Multi)LineString, flattened to [lon, lat]."""
    kind = geometry["type"]
    coordinates = geometry["coordinates"]
    if kind == "Polygon":
        polygons = [coordinates]
    elif kind == "MultiPolygon":
        polygons = coordinates
    elif kind == "LineString":
        return [coordinates]
    elif kind == "MultiLineString":
        return coordinates
    else:
        raise ValueError(f"unhandled geometry: {kind}")
    return [ring for polygon in polygons for ring in polygon]


def crosses(box: tuple, a: tuple, b: tuple) -> bool:
    """Whether the segment a–b passes through `box`, by bounding boxes."""
    return (
        min(a[0], b[0]) <= box[2]
        and max(a[0], b[0]) >= box[0]
        and min(a[1], b[1]) <= box[3]
        and max(a[1], b[1]) >= box[1]
    )


def clip(ring: list) -> list:
    """Keeps the runs of a ring that pass through the box, breaking where it leaves."""
    runs, current = [], []
    previous = None
    for lon, lat in ring:
        at = (lon, lat)
        if previous is None or crosses(CLIP, previous, at):
            current.append(at)
        elif current:
            runs.append(current)
            current = []
        previous = at
    if current:
        runs.append(current)
    return runs


def main() -> None:
    lines: dict[str, list] = {}
    for name, url in SOURCES.items():
        with urllib.request.urlopen(url, timeout=180) as response:
            data = json.load(response)
        collected, points_total = [], 0
        for feature in data["features"]:
            for ring in rings(feature["geometry"]):
                for run in clip(ring):
                    points = []
                    for lon, lat in run:
                        point = [round(lon, DECIMALS), round(lat, DECIMALS)]
                        if not points or points[-1] != point:
                            points.append(point)
                    if len(points) > 1:
                        collected.append(points)
                        points_total += len(points)
        lines[name] = collected
        print(f"{name}: {len(collected)} runs, {points_total} points")

    body = [
        "// Natural Earth 1:50m, public domain: coastlines and country borders, clipped to what",
        "// the radar can be drawn over and rounded to two decimals. Generated by",
        "// test/fixtures/make-basemap.py — edit the script, not this file.",
        "//",
        "// Deliberately not a `.pragma library`: the node test loads this file too, and a pragma",
        "// is QML-only syntax that plain JavaScript refuses.",
        "",
        f"var land = {json.dumps(lines['land'], separators=(',', ':'))}",
        "",
        f"var borders = {json.dumps(lines['borders'], separators=(',', ':'))}",
        "",
    ]
    TARGET.write_text("\n".join(body))
    print(f"wrote {TARGET} ({TARGET.stat().st_size // 1024} KB)")


if __name__ == "__main__":
    main()
